"""PDF86 (printed 159–160): Unit 16 Grammar C anaphoric and cataphoric references (definitions, examples), activity 1–5, exercise 1–12."""
from class12_book_common import Book, Builder

BOOK = Book('english')
v = Builder()
v.h('C. Anaphoric and Cataphoric References.', 'C. پیچھے اور آگے کی طرف اشارہ کرنے والے حوالے', 'C. شاته او مخکې اشاره کوونکې حوالې')
v.p('Anaphora and cataphora are two common forms of style that are used to reduce repetition and focus emphasis on specific ideas.', 'اینافورا اور کیٹافورا اسلوب کی دو عام صورتیں ہیں جو تکرار کم کرنے اور مخصوص خیالات پر زور دینے کے لیے استعمال ہوتی ہیں۔', 'انافورا او کاټافورا د سبک دوه عامې بڼې دي چې د تکرار د کمولو او په ځانګړو نظرونو د ټینګار لپاره کارول کېږي.')
v.h('Anaphora: (Anaphoric reference)', 'اینافورا: (پیچھے کی طرف حوالہ)', 'انافورا: (شاته حواله)')
v.p('Anaphora is a backward reference. The term has been derived from the Ancient Greek "ena" and "Phero" which means "a carrying back".', 'اینافورا پیچھے کی طرف حوالہ ہے۔ یہ اصطلاح قدیم یونانی "ena" اور "Phero" سے ماخوذ ہے جس کا مطلب ہے ’’پیچھے لے جانا‘‘۔', 'انافورا شاته حواله ده. دا اصطلاح له لرغوني یوناني "ena" او "Phero" څخه اخیستل شوې چې مانا یې "شاته وړل" ده.')
v.p('Linguistically, it means the use of a word or an expression in a text, the meaning of which is clarified when referred back to another word for expression (antecedent) used earlier in the text. For example,', 'لسانی طور پر اس کا مطلب متن میں کسی ایسے لفظ یا اظہار کا استعمال ہے جس کا مطلب متن میں پہلے استعمال ہونے والے کسی دوسرے لفظ یا اظہار (مرجع / antecedent) کی طرف رجوع کرنے سے واضح ہوتا ہے۔ مثلاً،', 'ژبپوهنیز ډول، دا په متن کې د داسې کلمې یا څرګندونې کارول دي چې مانا یې هغه وخت روښانه کېږي کله چې په متن کې مخکې کارول شوې بلې کلمې یا څرګندونې (مرجع / antecedent) ته شاته اشاره وشي. د بېلګې په توګه،')
v.group('list', [
    ('a. I met Aleena in the welcome party. She looked really awful." Here, the meaning of \'she\' is clarified when referred back to Aleena; and also, the repetition of the word Aleena is avoided.', 'a. I met Aleena in the welcome party. She looked really awful." یہاں ’she‘ کا مطلب علینہ کی طرف رجوع کرنے سے واضح ہوتا ہے؛ اور لفظ علینہ کی تکرار سے بھی بچا جاتا ہے۔', 'a. I met Aleena in the welcome party. She looked really awful." دلته د \'she\' مانا علینې ته په شاته اشاره روښانه کېږي؛ او د علینې د کلمې تکرار هم مخنیوی کېږي.'),
    ("b. Nazish dropped the glass. It shattered into fragments. Here, the pronoun 'it' is an anaphor which points to its antecedent 'the glass.", "b. Nazish dropped the glass. It shattered into fragments. یہاں ضمیر ’it‘ ایک اینافر ہے جو اپنے مرجع ’the glass‘ کی طرف اشارہ کرتا ہے۔", "b. Nazish dropped the glass. It shattered into fragments. دلته ضمیر 'it' یو انافر دی چې خپلې مرجع 'the glass' ته اشاره کوي."),
    ("c. If Haris buys a new cell phone, Abdullah will do it as well. Here, the verb phrase 'do it' is an anaphor referring back to its antecedent 'buys a new cell phone.'", "c. If Haris buys a new cell phone, Abdullah will do it as well. یہاں فعلیہ فقرہ ’do it‘ ایک اینافر ہے جو اپنے مرجع ’buys a new cell phone‘ کی طرف لوٹتا ہے۔", "c. If Haris buys a new cell phone, Abdullah will do it as well. دلته فعلي عبارت 'do it' یو انافر دی چې خپلې مرجع 'buys a new cell phone' ته شاته اشاره کوي."),
])
v.h('Cataphora: (Cataphoric reference)', 'کیٹافورا: (آگے کی طرف حوالہ)', 'کاټافورا: (مخکې حواله)')
v.p("It is the converse of Anaphora. It is a backward reference. The term has been derived from the Ancient Greek 'kata' and 'phero' which means carrying downwards.", "یہ اینافورا کا الٹ ہے۔ It is a backward reference [کتاب میں یوں ہی چھپا ہے]۔ یہ اصطلاح قدیم یونانی ’kata‘ اور ’phero‘ سے ماخوذ ہے جس کا مطلب ہے نیچے کی طرف لے جانا۔", "دا د انافورا پر عکس ده. It is a backward reference [په کتاب کې همداسې چاپ شوی]. دا اصطلاح له لرغوني یوناني 'kata' او 'phero' څخه اخیستل شوې چې مانا یې ښکته وړل دي.")
v.p('Linguistically, cataphora is a word or expression in a text that refers to another word or expression used later in the text ( Postcedent); So, one has to look ahead to understand its meaning. For example,', 'لسانی طور پر کیٹافورا متن میں ایسا لفظ یا اظہار ہے جو متن میں بعد میں استعمال ہونے والے کسی دوسرے لفظ یا اظہار (Postcedent) کی طرف اشارہ کرتا ہے؛ چنانچہ اس کا مطلب سمجھنے کے لیے آگے دیکھنا پڑتا ہے۔ مثلاً،', 'ژبپوهنیز ډول، کاټافورا په متن کې هغه کلمه یا څرګندونه ده چې په متن کې وروسته کارول شوې بلې کلمې یا څرګندونې (Postcedent) ته اشاره کوي؛ نو د مانا د پوهېدو لپاره باید مخکې وکتل شي. د بېلګې په توګه،')
v.group('list', [
    ('a. When he arrived, Afaq noticed that the window pane was broken. Here, the meaning of "he" is understood well when we look ahead at the word "Afaq". So \' he\' is used as a cataphor.', 'a. When he arrived, Afaq noticed that the window pane was broken. یہاں "he" کا مطلب اس وقت اچھی طرح سمجھ آتا ہے جب ہم آگے لفظ "Afaq" کو دیکھتے ہیں۔ لہٰذا ’he‘ کیٹافر کے طور پر استعمال ہوا ہے۔', 'a. When he arrived, Afaq noticed that the window pane was broken. دلته د "he" مانا هغه وخت ښه پوهېږو چې مخکې "Afaq" کلمې ته وګورو. نو \'he\' د کاټافر په توګه کارول شوی.'),
    ('b. His friends have been criticizing Umair for highlife. Here, the possessive adjective \'his\' is a cataphor pointing to its Postcedent "Umair"', 'b. His friends have been criticizing Umair for highlife. یہاں ملکیتی صفت ’his‘ ایک کیٹافر ہے جو اپنے Postcedent "Umair" کی طرف اشارہ کرتی ہے', 'b. His friends have been criticizing Umair for highlife. دلته ملکي صفت \'his\' یو کاټافر دی چې خپل Postcedent "Umair" ته اشاره کوي'),
    ('c. Although Haris might do so, Abdullah will not buy a new cell phone. Here, the verb phrase " do so" is a cataphor that points to its Postcedent " buy a new cell phone".', 'c. Although Haris might do so, Abdullah will not buy a new cell phone. یہاں فعلیہ فقرہ " do so" ایک کیٹافر ہے جو اپنے Postcedent " buy a new cell phone" کی طرف اشارہ کرتا ہے۔', 'c. Although Haris might do so, Abdullah will not buy a new cell phone. دلته فعلي عبارت " do so" یو کاټافر دی چې خپل Postcedent " buy a new cell phone" ته اشاره کوي.'),
])
v.h('Activity', 'سرگرمی', 'فعالیت')
v.p('1. Use the reading resource below.(Teacher may use any news article, narrative, or essay as well.)', '1. نیچے دیا گیا مطالعاتی مواد استعمال کریں۔ (استاد کوئی خبری مضمون، بیانیہ یا مضمون بھی استعمال کر سکتا ہے۔)', '1. لاندې د لوستلو سرچینه وکاروئ. (ښوونکی کولی شي هر خبري مقاله، روایت یا مقاله هم وکاروي.)')
R = '“Mario thought, should I tell her or shouldn’t I? The question spun round and round in his head and it slowly started to push every other logical argument to the sides, like a massive centrifuge. Slowly, though, he started to see the answers he needed. They were all lined up in neat little lists. And the first one was no, he shouldn’t!” ( The teacher may use a longer text if desired).'
v.p(R, R, R); v.paras[-1]['untranslatedByDesign'] = True
v.group('lines', [
    ('2. Scramble the clauses and give them to various groups of three students each. Each group should have the same materials. Ask them to match each clause together.', '2. شقوں (clauses) کو گڈمڈ کر کے تین تین طلبہ کے مختلف گروہوں کو دیں۔ ہر گروہ کے پاس ایک ہی مواد ہو۔ ان سے کہیں کہ ہر شق کو ملائیں۔', '2. فقرې (clauses) ګډوډې کړئ او د درې درې زده کوونکو بېلابېلو ډلو ته یې ورکړئ. هره ډله دې ورته مواد ولري. ترې وغواړئ چې هر فقره سره برابره کړي.'),
    ('3. After they have finished matching up the clauses. ask them to reorganize the sentences into a cohesive article.', '3. جب وہ شقیں ملا چکیں تو ان سے کہیں کہ جملوں کو ایک مربوط تحریر میں دوبارہ ترتیب دیں۔', '3. کله چې یې فقرې برابرې کړې، ترې وغواړئ چې جملې په یوه منسجمه مقاله کې بیا تنظیم کړي.'),
    ('4. After matching all the information together. spend a couple of minutes to ask a few comprehension questions on the original text ( Then, using the sentences from this activity as examples, teach the students anaphoric and cataphoric references.)', '4. تمام معلومات ملانے کے بعد چند منٹ اصل متن پر فہم کے چند سوالات پوچھنے میں صرف کریں (پھر اس سرگرمی کے جملوں کو مثال بنا کر طلبہ کو anaphoric اور cataphoric حوالے سکھائیں۔)', '4. د ټولو معلوماتو له برابرولو وروسته، څو دقیقې په اصلي متن د پوهې ځینې پوښتنو ته ورکړئ (بیا د دې فعالیت جملې د بېلګې په توګه وکاروئ او زده کوونکو ته anaphoric او cataphoric حوالې ور زده کړئ.)'),
    ('5. Finally, ask the students to pick a trending topic from the news to write a few sentences about .Tell the students to divide the clauses onto several strips pieces of paper. When each group has finished writing five sentences, allow them to exchange their clauses with the group to their left which will be supposed to match the clauses together to make a cohesive paragraph of it.', '5. آخر میں طلبہ سے کہیں کہ خبروں سے کوئی مقبول موضوع چن کر اس پر چند جملے لکھیں۔ طلبہ سے کہیں کہ شقوں کو کاغذ کی کئی پٹیوں پر تقسیم کریں۔ جب ہر گروہ پانچ جملے لکھ چکے تو انہیں اپنی شقیں بائیں جانب والے گروہ سے تبدیل کرنے دیں، جو شقوں کو ملا کر ایک مربوط پیراگراف بنائے گا۔', '5. په پای کې زده کوونکو ته ووایئ چې له خبرونو یوه رواجي موضوع وټاکي او په اړه یې څو جملې ولیکي. زده کوونکو ته ووایئ چې فقرې د کاغذ په څو پټو ووېشي. کله چې هرې ډلې پنځه جملې ولیکلې، اجازه ورکړئ چې خپلې فقرې له کیڼ لوري ډلې سره بدلې کړي، چې باید فقرې سره برابرې کړي او یو منسجم پراګراف ترې جوړ کړي.'),
])
v.h('Exercise', 'مشق', 'تمرین')
v.p('Read the following sentences carefully and tell whether the word/expression in italics is an anaphor or a cataphor. Also mention its antecedent/ Postcedent.', 'درج ذیل جملے غور سے پڑھیں اور بتائیں کہ ترچھے (italics) لفظ/اظہار اینافر ہے یا کیٹافر۔ اس کا مرجع/ Postcedent بھی بتائیں۔', 'لاندې جملې په دقت ولولئ او ووایئ چې په کږو تورو (italics) کلمه/څرګندونه انافر ده که کاټافر. د هغې مرجع/ Postcedent هم یاده کړئ.')
E = ['Hurain and her parents visited Dubai last year. They had such a great time together . [italics: They]', 'Hamad bought a new motorbike yesterday. He loves his new motorbike very much. [italics: He]', 'One day, while he was washing clothes, a big peach floated down the stream. The old washerman took the peach home. [italics: he]',
     "One morning, a terrorist group attacked the village. It stole all the villagers' belongings and destroyed most of their houses. [italics: It, their]", 'During his early rehearsals , an actor may forget his lines. [italics: his, his]', 'The Qatar team was opportunistic; it took advantage of every break. [italics: it]',
     'A person needs to see his dentist twice a year. [italics: his]', 'If any one of the sisters needs a ride,she can call me. [italics: she]', 'If someone has been drinking, he may drive poorly. [italics: he]', 'Neither the pilot nor the attendants gave their opinion about the mishap. [italics: their]',
     'Each of these companies had its books audited. [italics: its]', 'Umair says that If you need help with your grammar, you may see him. [italics: your, him]']
v.group('lines', [(f'{i}. {s}',) * 3 for i, s in enumerate(E, 1)])
for p in v.paras[-len(E):]: p['untranslatedByDesign'] = True
rec = BOOK.record(v, 'eng12-u16-vocab-c', 'C Anaphoric and cataphoric references; activity; exercise', 'C پیچھے اور آگے کے حوالے؛ سرگرمی؛ مشق', 'C شاته او مخکې حوالې؛ فعالیت؛ تمرین', 86, [159, 160])
issues = [{'id': 'eng12-p159-160', 'unit': 16, 'printedPage': 159, 'description': 'Printed text retained: cataphora is defined as “a backward reference” (should be forward); “another word for expression”; Greek glosses “ena”/“Phero”; stray closing quote in example a; “for highlife”; “strips pieces of paper”; “If you need help” with capital I. Italicised target words in the exercise are shown as “[italics: …]”; no exercise sentences are marked as such in the book beyond italics. Section lettering starts at C (A and B are the vocabulary exercises on p.158).'}]

